const jsContent = `const api = "/v1/contact-face-v6";
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const ui = Object.fromEntries([...document.querySelectorAll("[id]")].map((element) => [element.id, element]));

let mode = "pending_review";
let items = [];
let index = -1;
let draft = null;
let saved = null;
let image = null;
let dirty = false;
let tool = "point";
let drag = null;

function msg(text, error = false) {
  ui.message.textContent = text;
  ui.message.style.background = error ? "#f7d6cf" : "#e6f1e8";
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function canLeave() {
  return !dirty || confirm("当前设备框或接触点尚未保存，确定放弃吗？");
}

async function request(url, options = {}) {
  const response = await fetch(url, { cache: "no-store", ...options });
  const data = await response.json();
  if (!response.ok || data.ok === false) {
    throw new Error(data.error || \`请求失败 \${response.status}\`);
  }
  return data;
}

function setDirty(message = "当前有未保存的人工修改。") {
  dirty = true;
  ui.message.classList.add("dirty");
  msg(message);
}

function canvasPoint(event) {
  const rect = canvas.getBoundingClientRect();
  return [
    Math.max(0, Math.min(canvas.width, (event.clientX - rect.left) * canvas.width / rect.width)),
    Math.max(0, Math.min(canvas.height, (event.clientY - rect.top) * canvas.height / rect.height)),
  ];
}

function normalizeBox(a, b) {
  return [
    Math.min(a[0], b[0]),
    Math.min(a[1], b[1]),
    Math.max(a[0], b[0]),
    Math.max(a[1], b[1]),
  ];
}

function validBox(box) {
  return box && box.length === 4 && box[2] - box[0] >= 4 && box[3] - box[1] >= 4;
}

function handles(box) {
  if (!box) return {};
  return {
    nw: [box[0], box[1]],
    ne: [box[2], box[1]],
    sw: [box[0], box[3]],
    se: [box[2], box[3]],
  };
}

function hitRadius() {
  const rect = canvas.getBoundingClientRect();
  return Math.max(8, 13 * canvas.width / Math.max(rect.width, 1));
}

function hitHandle(point, box) {
  const radius = hitRadius();
  for (const [name, handle] of Object.entries(handles(box))) {
    if (Math.hypot(point[0] - handle[0], point[1] - handle[1]) <= radius) return name;
  }
  return null;
}

function pointInside(point, box) {
  return Boolean(box && point[0] >= box[0] && point[0] <= box[2] && point[1] >= box[1] && point[1] <= box[3]);
}

function setTool(next) {
  tool = next;
  drag = null;
  ui.adjustBox.classList.toggle("tool-active", next === "adjust");
  ui.redrawBox.classList.toggle("tool-active", next === "redraw");
  ui.pointTool.classList.toggle("tool-active", next === "point");
  canvas.style.cursor = next === "point" ? "crosshair" : next === "redraw" ? "crosshair" : "move";
  const messages = {
    point: "请点击设备治疗头与人脸接触的位置，新点会覆盖旧点。",
    adjust: "拖动黄色框体可移动，拖动四角白色控制点可缩放。",
    redraw: "请按住鼠标从设备框一个角拖到另一个角，松开后完成新框。",
  };
  msg(messages[next]);
  render();
}

function render() {
  if (!image || !draft) return;
  canvas.width = image.width;
  canvas.height = image.height;
  ctx.drawImage(image, 0, 0);

  const box = draft.device_bbox;
  if (box) {
    ctx.strokeStyle = "#e3b341";
    ctx.lineWidth = Math.max(4, Math.min(canvas.width, canvas.height) * 0.006);
    ctx.strokeRect(box[0], box[1], box[2] - box[0], box[3] - box[1]);
    if (tool === "adjust" || tool === "redraw") {
      const size = Math.max(10, Math.min(canvas.width, canvas.height) * 0.016);
      for (const handle of Object.values(handles(box))) {
        ctx.fillStyle = "#ffffff";
        ctx.strokeStyle = "#e3b341";
        ctx.lineWidth = Math.max(2, size * 0.18);
        ctx.fillRect(handle[0] - size / 2, handle[1] - size / 2, size, size);
        ctx.strokeRect(handle[0] - size / 2, handle[1] - size / 2, size, size);
      }
    }
  }

  const point = draft.contact_point;
  if (point) {
    const radius = Math.max(8, Math.min(canvas.width, canvas.height) * 0.012);
    ctx.beginPath();
    ctx.arc(point[0], point[1], radius, 0, Math.PI * 2);
    ctx.fillStyle = "#9b36d6";
    ctx.fill();
    ctx.strokeStyle = "white";
    ctx.lineWidth = 3;
    ctx.stroke();
  }

  const contactText = point
    ? \`有接触点 (\${point[0].toFixed(1)}, \${point[1].toFixed(1)})\`
    : "设备未接触人脸（接触点为空）";
  ui.contactStatus.textContent = \`当前：\${contactText}；设备框可人工修正\`;
}

function listView() {
  ui.samples.replaceChildren();
  items.forEach((item, itemIndex) => {
    const button = document.createElement("button");
    button.className = \`sample\${itemIndex === index ? " current" : ""}\`;
    button.innerHTML = \`<strong>\${itemIndex + 1}. \${item.sample_id}</strong>\${item.anonymous_subject_id} / \${item.logical_split}\`;
    button.onclick = () => {
      if (canLeave()) load(itemIndex);
    };
    ui.samples.append(button);
  });
  if (!items.length) ui.samples.textContent = "当前列表已完成。";
}

async function status() {
  const state = await request(api + "/status");
  ui.gate.textContent = \`已审查 \${state.confirmed}/\${state.total} ｜ 未接触 \${state.not_in_contact}/\${state.not_in_contact_target}\`;
  ui.pending.textContent = \`待审查 \${state.pending_review}\`;
  ui.confirmed.textContent = \`已审查 \${state.confirmed}\`;
}

async function loadList(preferred = 0) {
  const data = await request(\`\${api}/samples?review_state=\${mode}\`);
  items = data.items;
  index = -1;
  draft = null;
  saved = null;
  image = null;
  dirty = false;
  listView();
  if (items.length) {
    await load(Math.min(preferred, items.length - 1));
  } else {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ui.contactStatus.textContent = "当前列表已完成";
  }
  await status();
}

async function load(itemIndex) {
  const item = items[itemIndex];
  const data = await request(\`\${api}/samples/\${encodeURIComponent(item.sample_id)}\`);
  index = itemIndex;
  draft = clone(data.annotation);
  saved = clone(data.annotation);
  dirty = false;
  drag = null;
  ui.message.classList.remove("dirty");
  const response = await fetch(\`\${api}/samples/\${encodeURIComponent(item.sample_id)}/image\`, { cache: "no-store" });
  image = await createImageBitmap(await response.blob());
  setTool("point");
  listView();
  msg(draft.contact_point
    ? "框正确时只需检查接触点；框错误可点击上方按钮修正。"
    : "没有接触点将按“设备未接触人脸”保存；框错误可先修正。");
}

canvas.addEventListener("pointerdown", (event) => {
  if (!draft || !image) return;
  const point = canvasPoint(event);

  if (tool === "point") {
    draft.contact_point = point;
    setDirty("接触点已修改，尚未保存。");
    render();
    return;
  }

  const original = clone(draft.device_bbox);
  if (tool === "redraw") {
    drag = { kind: "draw", start: point, original };
    draft.device_bbox = [point[0], point[1], point[0], point[1]];
  } else {
    const handle = hitHandle(point, draft.device_bbox);
    if (handle) {
      drag = { kind: "resize", handle, start: point, original };
    } else if (pointInside(point, draft.device_bbox)) {
      drag = { kind: "move", start: point, original };
    } else {
      msg("请拖动黄色框体或四角控制点；需要在别处重画请点“重新画设备框”。", true);
      return;
    }
  }
  canvas.setPointerCapture(event.pointerId);
  event.preventDefault();
});

canvas.addEventListener("pointermove", (event) => {
  if (!draft || !drag) return;
  const point = canvasPoint(event);
  const original = drag.original;

  if (drag.kind === "draw") {
    draft.device_bbox = normalizeBox(drag.start, point);
  } else if (drag.kind === "move") {
    const width = original[2] - original[0];
    const height = original[3] - original[1];
    const dx = point[0] - drag.start[0];
    const dy = point[1] - drag.start[1];
    const x1 = Math.max(0, Math.min(canvas.width - width, original[0] + dx));
    const y1 = Math.max(0, Math.min(canvas.height - height, original[1] + dy));
    draft.device_bbox = [x1, y1, x1 + width, y1 + height];
  } else if (drag.kind === "resize") {
    let [x1, y1, x2, y2] = original;
    if (drag.handle.includes("n")) y1 = Math.min(point[1], y2 - 4);
    if (drag.handle.includes("s")) y2 = Math.max(point[1], y1 + 4);
    if (drag.handle.includes("w")) x1 = Math.min(point[0], x2 - 4);
    if (drag.handle.includes("e")) x2 = Math.max(point[0], x1 + 4);
    draft.device_bbox = [
      Math.max(0, x1),
      Math.max(0, y1),
      Math.min(canvas.width, x2),
      Math.min(canvas.height, y2),
    ];
  }

  render();
  event.preventDefault();
});

function finishDrag(event) {
  if (!drag || !draft) return;
  if (!validBox(draft.device_bbox)) {
    draft.device_bbox = drag.original;
    msg("新设备框过小，已恢复原框。", true);
  } else {
    setDirty("设备框已修改，尚未保存。");
  }
  drag = null;
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  render();
}

canvas.addEventListener("pointerup", finishDrag);
canvas.addEventListener("pointercancel", (event) => {
  if (drag && draft) draft.device_bbox = drag.original;
  drag = null;
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  render();
});

ui.adjustBox.onclick = () => setTool("adjust");
ui.redrawBox.onclick = () => setTool("redraw");
ui.pointTool.onclick = () => setTool("point");
ui.clearPoint.onclick = () => {
  if (!draft) return;
  draft.contact_point = null;
  setDirty("接触点已清除，将保存为设备未接触人脸。");
  render();
};
ui.discard.onclick = () => {
  if (!draft) return;
  draft = clone(saved);
  dirty = false;
  drag = null;
  ui.message.classList.remove("dirty");
  setTool("point");
  msg("已放弃本张修改。");
};
ui.saveNext.onclick = async () => {
  if (!draft) return;
  if (!validBox(draft.device_bbox)) {
    msg("保存失败：设备框无效，请重新绘制。", true);
    return;
  }
  const previousIndex = index;
  try {
    await request(\`\${api}/samples/\${encodeURIComponent(draft.sample_id)}/review\`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        device_bbox: draft.device_bbox,
        contact_point: draft.contact_point,
      }),
    });
    dirty = false;
    await loadList(previousIndex);
  } catch (error) {
    msg(\`保存失败：\${error.message}\`, true);
  }
};

async function switchMode(next) {
  if (next === mode || !canLeave()) return;
  mode = next;
  ui.pending.classList.toggle("active", mode === "pending_review");
  ui.confirmed.classList.toggle("active", mode === "confirmed");
  await loadList();
}

ui.pending.onclick = () => switchMode("pending_review");
ui.confirmed.onclick = () => switchMode("confirmed");
window.onbeforeunload = (event) => {
  if (dirty) {
    event.preventDefault();
    event.returnValue = "";
  }
};

loadList().catch((error) => msg(\`页面初始化失败：\${error.message}\`, true));
