    : "没有接触点将按“设备未接触人脸”保存；框错误可先修正。");
}

canvas.addEventListener("pointerdown", (event) => {
  if (!draft || !image) return;
  const point = canvasPoint(event);

  if (tool === "point") {
    if (draft.status !== "device" || !validBox(draft.device_bbox)) {
      msg("当前已标记为无设备；如需恢复，请先点击“重新画设备框”。", true);
      return;
    }
    draft.contact_point = point;
    setDirty("接触点已修改，尚未保存。");
    render();
    return;
  }

  const original = clone(draft.device_bbox);
  if (tool === "redraw") {
    drag = { kind: "draw", start: point, original };
    draft.device_bbox = [point[0], point[1], point[0], point[1]];
  } else {
    const handle = hitHandle(point, draft.device_bbox);
    if (handle) {
      drag = { kind: "resize", handle, start: point, original };
    } else if (pointInside(point, draft.device_bbox)) {
      drag = { kind: "move", start: point, original };
    } else {
      msg("请拖动黄色框体或四角控制点；需要在别处重画请点“重新画设备框”。", true);
      return;
    }
  }
  canvas.setPointerCapture(event.pointerId);
  event.preventDefault();
});

canvas.addEventListener("pointermove", (event) => {
  if (!draft || !drag) return;
  const point = canvasPoint(event);
  const original = drag.original;

  if (drag.kind === "draw") {
    draft.device_bbox = normalizeBox(drag.start, point);
  } else if (drag.kind === "move") {
    const width = original[2] - original[0];
    const height = original[3] - original[1];
    const dx = point[0] - drag.start[0];
    const dy = point[1] - drag.start[1];
    const x1 = Math.max(0, Math.min(canvas.width - width, original[0] + dx));
    const y1 = Math.max(0, Math.min(canvas.height - height, original[1] + dy));
    draft.device_bbox = [x1, y1, x1 + width, y1 + height];
  } else if (drag.kind === "resize") {
    let [x1, y1, x2, y2] = original;
    if (drag.handle.includes("n")) y1 = Math.min(point[1], y2 - 4);
    if (drag.handle.includes("s")) y2 = Math.max(point[1], y1 + 4);
    if (drag.handle.includes("w")) x1 = Math.min(point[0], x2 - 4);
    if (drag.handle.includes("e")) x2 = Math.max(point[0], x1 + 4);
    draft.device_bbox = [
      Math.max(0, x1),
      Math.max(0, y1),
      Math.min(canvas.width, x2),
      Math.min(canvas.height, y2),
    ];
  }

  render();
  event.preventDefault();
});

function finishDrag(event) {
  if (!drag || !draft) return;
  if (!validBox(draft.device_bbox)) {
    draft.device_bbox = drag.original;
    msg("新设备框过小，已恢复原框。", true);
  } else {
    draft.status = "device";
    setDirty("设备框已修改，尚未保存。");
  }
  drag = null;
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  render();
}

canvas.addEventListener("pointerup", finishDrag);
canvas.addEventListener("pointercancel", (event) => {
  if (drag && draft) draft.device_bbox = drag.original;
  drag = null;
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  render();
});

