async function updateModes(nextManual, nextMarker) {
  manualModeBtn.disabled = true;
  markerModeBtn.disabled = true;
  try {
    const response = await fetch("/v1/assist/modes", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        enable_manual_bbox_assist: nextManual,
        enable_marker_assist: nextMarker,
      }),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    applyModes(data.assist_modes);
    status("è¾…åŠ©æ¨¡å¼å·²æ›´æ–°ï¼šæ‰‹åŠ¨ç”»æ¡†" + (manualEnabled ? "å¼€å¯" : "å…³é—­") +
      "ï¼ŒAprilTag" + (markerEnabled ? "å¼€å¯" : "å…³é—­") + "ã€‚");
  } catch (error) {
    status("è¾…åŠ©æ¨¡å¼æ›´æ–°å¤±è´¥ï¼š" + error.message, true);
  } finally {
    manualModeBtn.disabled = false;
    markerModeBtn.disabled = false;
  }
}

function fit() {
  if (!video.videoWidth) return;
  for (const target of [canvas, capture, seed]) {
    if (target.width !== video.videoWidth || target.height !== video.videoHeight) {
      target.width = video.videoWidth;
      target.height = video.videoHeight;
    }
  }
}

function validBox(box) {
  return Array.isArray(box) && box.length === 4 &&
    box.every(Number.isFinite) && box[2] > box[0] && box[3] > box[1];
}

function validPoint(point) {
  return Array.isArray(point) && point.length === 2 && point.every(Number.isFinite);
}

function rememberResult(result, receivedAt) {
  latest = result;
  latestReceivedAt = receivedAt;
  if (result.state === "TRACKING" && validBox(result.device_bbox)) {
    boxSamples.push({time: receivedAt, value: result.device_bbox.map(Number)});
    boxSamples = boxSamples.slice(-2);
    if (validPoint(result.contact_point) &&
        result.contact_visibility !== "not_annotatable" &&
        (result.contact_updated !== false || pointSamples.length === 0)) {
      pointSamples.push({time: receivedAt, value: result.contact_point.map(Number)});
      pointSamples = pointSamples.slice(-2);
    }
  } else if (result.state === "LOST" || result.state === "SEARCHING") {
    boxSamples = [];
    pointSamples = [];
  } else if (result.state === "UNCERTAIN") {
    pointSamples = [];
  }
