    ctx.save();
    ctx.strokeStyle = "#18a56f";
    ctx.fillStyle = "#18a56f";
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let index = 1; index < 4; index += 1) ctx.lineTo(points[index][0], points[index][1]);
    ctx.closePath();
    ctx.stroke();
    ctx.font = "bold 22px sans-serif";
