  ctx.beginPath();
  ctx.moveTo(polygon[0][0], polygon[0][1]);
  for (let index = 1; index < polygon.length; index += 1) {
    ctx.lineTo(polygon[index][0], polygon[index][1]);
  }
  ctx.closePath();
  ctx.clip();
  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
  ctx.restore();
}

function paint(now) {
  renderFrames += 1;
  if (canvas.width) {
    if (frozen) ctx.drawImage(seed, 0, 0);
    else if (video.videoWidth) drawLiveFrame();

    if (!frozen && latest) {
      const debugMode = inferenceSettings.view_mode === "debug";
      if (debugMode) {
        drawForegroundOutline(foregroundPolygon());
        drawMarkers(latest.marker_corners);
        drawBox(latest.diagnostic_bbox, "#f58b23", "è‡ªåŠ¨å€™é€‰", 4);
      }
      const smoothBox = interpolateSamples(boxSamples, now, "box");
      if (latest.state === "TRACKING") {
        drawBox(smoothBox, "#ed3343", "TRACKING");
        drawPoint(interpolateSamples(pointSamples, now, "point"));
      } else if (debugMode && latest.state === "UNCERTAIN") {
        drawBox(smoothBox, "#ffd64a", "UNCERTAIN", 5, true);
      } else if (debugMode && latest.state === "CANDIDATE") {
        drawBox(latest.device_bbox, "#f58b23", "CANDIDATE", 4);
      }
