function contactRegionText() {
  if (!latest || !validPoint(latest.contact_point)) return "";
  const label = String(latest.contact_region_label_zh || "");
  if (!label || label === "\u672a\u77e5") return "";
  const confidence = Number(latest.contact_region_confidence || 0);
  return label + (confidence > 0 ? " " + confidence.toFixed(2) : "");
}

function drawLiveFrame() {
  const rawPolygon = foregroundPolygon();
  const polygon = displayPolygon(rawPolygon);
  const displayBackground = inferenceSettings.view_mode === "presentation"
    ? "raw" : inferenceSettings.display_background;
  if (displayBackground === "raw" || polygon.length < 3) {
    drawImageSource(video);
    return;
  }
  ctx.save();
  ctx.fillStyle = displayBackground === "white" ? "#fff" : "#000";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.moveTo(polygon[0][0], polygon[0][1]);
  for (let index = 1; index < polygon.length; index += 1) {
    ctx.lineTo(polygon[index][0], polygon[index][1]);
  }
  ctx.closePath();
  ctx.clip();
  drawImageSource(video);
  ctx.restore();
}

function paint(now) {
  renderFrames += 1;
  if (canvas.width) {
    if (frozen) drawImageSource(seed);
    else if (video.videoWidth) drawLiveFrame();

    if (!frozen && latest) {
      const debugMode = inferenceSettings.view_mode === "debug";
      if (debugMode) {
        drawFaceMesh();
        drawForegroundOutline(foregroundPolygon());
        drawMarkers(latest.marker_corners);
        drawBox(latest.diagnostic_bbox, "#f58b23", "è‡ªåŠ¨å€™é€‰", 4);
      }
      const smoothBox = interpolateSamples(boxSamples, now, "box");
      if (latest.state === "TRACKING") {
        drawBox(smoothBox, "#ed3343", "TRACKING");
        drawPoint(interpolateSamples(pointSamples, now, "point"), contactRegionText());
      } else if (debugMode && latest.state === "UNCERTAIN") {
        drawBox(smoothBox, "#ffd64a", "UNCERTAIN", 5, true);
      } else if (debugMode && latest.state === "CANDIDATE") {
        drawBox(latest.device_bbox, "#f58b23", "CANDIDATE", 4);
      }
