#include <cmath>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <string>

#include "medvision/geometry.hpp"
#include "medvision/postprocess.hpp"
#include "medvision/tensor_io.hpp"

#ifdef MEDVISION_WITH_ONNXRUNTIME
#include "medvision/onnx_runtime_backend.hpp"
#endif

int main(int argc, char** argv) {
    if (argc == 2 && std::string(argv[1]) == "--self-test") {
        const auto transform = medvision::make_letterbox(4032, 3024, 640, 640);
        const auto original = medvision::from_letterbox(medvision::to_letterbox({123.0F, 456.0F}, transform), transform);
        if (std::abs(original.x - 123.0F) > 0.001F || std::abs(original.y - 456.0F) > 0.001F) {
            std::cerr << "MEDVISION_SELF_TEST=FAIL\n";
            return EXIT_FAILURE;
        }
        std::cout << "MEDVISION_SELF_TEST=PASS\n";
        return EXIT_SUCCESS;
    }
    if (argc == 10 && std::string(argv[1]) == "--decode-contact") {
        const auto width = static_cast<std::size_t>(std::stoul(argv[3]));
        const auto height = static_cast<std::size_t>(std::stoul(argv[4]));
        const medvision::BBox roi{
            std::stof(argv[5]), std::stof(argv[6]), std::stof(argv[7]), std::stof(argv[8])};
        const auto radius = static_cast<std::size_t>(std::stoul(argv[9]));
        const auto heatmap = medvision::read_float_tensor(argv[2], width * height);
        const auto point = medvision::decode_heatmap_peak_neighborhood(
            heatmap, width, height, roi, radius);
        std::cout << std::setprecision(10)
                  << "CONTACT_DECODE=PASS x=" << point.x << " y=" << point.y << "\n";
        return EXIT_SUCCESS;
    }
#ifdef MEDVISION_WITH_ONNXRUNTIME
    if (argc == 3 && std::string(argv[1]) == "--check-model") {
        medvision::OnnxRuntimeBackend backend;
        backend.load(argv[2]);
        std::cout << "MODEL_LOAD=PASS backend=" << backend.name() << "\n";
        return EXIT_SUCCESS;
    }
    if (argc == 3 && std::string(argv[1]) == "--run-smoke") {
        medvision::OnnxRuntimeBackend backend;
        backend.load(argv[2]);
        medvision::Tensor input{{1, 3, 4, 4}, std::vector<float>(48, 1.0F)};
        const auto outputs = backend.run(input);
        if (outputs.size() != 1 || outputs[0].shape != input.shape || outputs[0].values.size() != input.values.size()) {
            std::cerr << "ONNX_RUNTIME_SMOKE=FAIL reason=output_shape\n";
            return EXIT_FAILURE;
        }
        for (const float value : outputs[0].values) {
            if (std::abs(value - 2.0F) > 1e-6F) {
                std::cerr << "ONNX_RUNTIME_SMOKE=FAIL reason=output_value\n";
                return EXIT_FAILURE;
            }
        }
        std::cout << "ONNX_RUNTIME_SMOKE=PASS backend=" << backend.name() << "\n";
        return EXIT_SUCCESS;
    }
    if (argc == 6 && std::string(argv[1]) == "--run-tensor") {
        const auto shape = medvision::parse_tensor_shape(argv[5]);
        const auto count = medvision::tensor_element_count(shape);
        medvision::OnnxRuntimeBackend backend;
        backend.load(argv[2]);
        const auto outputs = backend.run({shape, medvision::read_float_tensor(argv[3], count)});
        if (outputs.empty()) {
            throw std::runtime_error("ONNX model returned no outputs");
        }
        medvision::write_float_tensor(argv[4], outputs.front());
        std::cout << "ONNX_TENSOR_RUN=PASS backend=" << backend.name()
                  << " values=" << outputs.front().values.size() << " shape=";
        for (std::size_t index = 0; index < outputs.front().shape.size(); ++index) {
            std::cout << (index == 0 ? "" : ",") << outputs.front().shape[index];
        }
        std::cout << "\n";
        return EXIT_SUCCESS;
    }
#endif
    std::cerr << "Usage: medvision_cli --self-test"
              << " | --decode-contact HEATMAP.bin WIDTH HEIGHT X1 Y1 X2 Y2 RADIUS";
#ifdef MEDVISION_WITH_ONNXRUNTIME
    std::cerr << " | --check-model MODEL.onnx | --run-smoke TEST_MODEL.onnx"
              << " | --run-tensor MODEL.onnx INPUT.bin OUTPUT.bin SHAPE";
#endif
    std::cerr << "\n";
    return EXIT_FAILURE;
}
