Json percentile_json(const std::vector<double>& values, double fraction) {
    if (values.empty()) return nullptr;
    auto ordered = values;
    std::sort(ordered.begin(), ordered.end());
    const auto index = static_cast<std::size_t>(std::clamp(
        std::ceil(fraction * static_cast<double>(ordered.size())) - 1.0, 0.0, static_cast<double>(ordered.size() - 1)));
    return ordered[index];
}

Json metrics_json(const StreamSession& session) {
