        std::accumulate(metrics.total_latency_ms.begin(), metrics.total_latency_ms.end(), 0.0);
    return {{"session_id", session.id}, {"stopped", session.stopped},
            {"processed_frames", metrics.processed_frames}, {"detection_frames", metrics.detection_frames},
            {"holding_frames", metrics.holding_frames}, {"lost_frames", metrics.lost_frames},
            {"reacquisition_count", metrics.reacquisition_count}, {"contact_valid_frames", metrics.contact_valid_frames},
            {"average_fps", fps}, {"p50_total_server_ms", percentile_json(metrics.total_latency_ms, 0.50)},
