#include <string>

#include "medvision/types.hpp"

namespace medvision {

enum class TrackState {
    NoTarget,
    Tracking,
    Holding,
    Lost,
};

struct TrackerConfig {
    std::int64_t max_hold_ms{250};
    float min_iou{0.15F};
    float max_center_shift_ratio{1.35F};
};

struct TrackerUpdate {
    TrackState state{TrackState::NoTarget};
    std::optional<BBox> bbox;
    bool raw_detection_found{};
    bool detection_accepted{};
    bool stale{};
    bool prediction_used{};
    bool reacquired{};
    std::string reason;
};

class SingleDeviceTracker {
public:
    explicit SingleDeviceTracker(TrackerConfig config = {});

    [[nodiscard]] TrackerUpdate update(
        const std::optional<DeviceDetection>& detection,
        std::int64_t timestamp_ms);
    void reset();
    [[nodiscard]] TrackState state() const noexcept;

private:
    [[nodiscard]] BBox predicted(std::int64_t timestamp_ms) const;
    void initialize(const BBox& measurement, std::int64_t timestamp_ms);
    void correct(const BBox& measurement, std::int64_t timestamp_ms);
    [[nodiscard]] bool plausible(const BBox& measurement, const BBox& prediction) const;

    TrackerConfig config_;
    TrackState state_{TrackState::NoTarget};
    bool initialized_{};
    float cx_{};
    float cy_{};
    float width_{};
    float height_{};
    float vx_{};
    float vy_{};
    float vw_{};
    float vh_{};
    std::int64_t last_measurement_ms{};
    std::int64_t last_update_ms{};
};

[[nodiscard]] std::string to_string(TrackState state);

}  // namespace medvision
#include "medvision/single_device_tracker.hpp"

#include <algorithm>
#include <cmath>

#include "medvision/geometry.hpp"

namespace medvision {
namespace {

constexpr float kMinimumSize = 2.0F;

bool valid(const BBox& box) {
    return std::isfinite(box.x1) && std::isfinite(box.y1) && std::isfinite(box.x2)
        && std::isfinite(box.y2) && box.x2 - box.x1 >= kMinimumSize
        && box.y2 - box.y1 >= kMinimumSize;
}

float center_distance(const BBox& left, const BBox& right) {
    const float dx = (left.x1 + left.x2 - right.x1 - right.x2) * 0.5F;
    const float dy = (left.y1 + left.y2 - right.y1 - right.y2) * 0.5F;
    return std::sqrt(dx * dx + dy * dy);
}

float diagonal(const BBox& box) {
    const float width = box.x2 - box.x1;
    const float height = box.y2 - box.y1;
    return std::max(kMinimumSize, std::sqrt(width * width + height * height));
}

}  // namespace

SingleDeviceTracker::SingleDeviceTracker(TrackerConfig config) : config_(config) {}

TrackerUpdate SingleDeviceTracker::update(
    const std::optional<DeviceDetection>& detection,
    std::int64_t timestamp_ms) {
    TrackerUpdate update;
    update.raw_detection_found = detection.has_value() && valid(detection->bbox);
    const bool has_prediction = initialized_;
    const BBox prediction = has_prediction ? predicted(timestamp_ms) : BBox{};

    if (update.raw_detection_found && (!has_prediction || plausible(detection->bbox, prediction)
                                       || state_ == TrackState::Lost || state_ == TrackState::NoTarget)) {
        update.reacquired = state_ == TrackState::Holding || state_ == TrackState::Lost;
        if (!initialized_ || state_ == TrackState::Lost || state_ == TrackState::NoTarget) {
            initialize(detection->bbox, timestamp_ms);
        } else {
            correct(detection->bbox, timestamp_ms);
        }
        state_ = TrackState::Tracking;
        update.state = state_;
        update.bbox = predicted(timestamp_ms);
        update.detection_accepted = true;
        update.reason = update.reacquired ? "detection_reacquired" : "raw_detection_accepted";
        return update;
    }

    if (update.raw_detection_found) {
        update.reason = "raw_detection_rejected_by_motion_gate";
    } else {
        update.reason = "raw_detection_missing";
    }
    if (initialized_ && timestamp_ms >= last_measurement_ms
        && timestamp_ms - last_measurement_ms <= config_.max_hold_ms) {
        state_ = TrackState::Holding;
        update.state = state_;
        update.bbox = prediction;
        update.stale = true;
        update.prediction_used = true;
        last_update_ms = timestamp_ms;
        return update;
    }

    state_ = initialized_ ? TrackState::Lost : TrackState::NoTarget;
    update.state = state_;
    update.reason = initialized_ ? "hold_timeout" : update.reason;
    return update;
}

void SingleDeviceTracker::reset() {
    initialized_ = false;
    state_ = TrackState::NoTarget;
    cx_ = cy_ = width_ = height_ = vx_ = vy_ = vw_ = vh_ = 0.0F;
    last_measurement_ms = last_update_ms = 0;
}

TrackState SingleDeviceTracker::state() const noexcept {
    return state_;
}

BBox SingleDeviceTracker::predicted(std::int64_t timestamp_ms) const {
    const float elapsed = std::clamp(
        static_cast<float>(std::max<std::int64_t>(0, timestamp_ms - last_update_ms)) / 1000.0F,
        0.0F,
        0.25F);
    const float cx = cx_ + vx_ * elapsed;
    const float cy = cy_ + vy_ * elapsed;
    const float width = std::max(kMinimumSize, width_ + vw_ * elapsed);
    const float height = std::max(kMinimumSize, height_ + vh_ * elapsed);
    return {cx - width * 0.5F, cy - height * 0.5F, cx + width * 0.5F, cy + height * 0.5F};
}

void SingleDeviceTracker::initialize(const BBox& measurement, std::int64_t timestamp_ms) {
    cx_ = (measurement.x1 + measurement.x2) * 0.5F;
    cy_ = (measurement.y1 + measurement.y2) * 0.5F;
    width_ = measurement.x2 - measurement.x1;
    height_ = measurement.y2 - measurement.y1;
    vx_ = vy_ = vw_ = vh_ = 0.0F;
    initialized_ = true;
    last_measurement_ms = last_update_ms = timestamp_ms;
}

void SingleDeviceTracker::correct(const BBox& measurement, std::int64_t timestamp_ms) {
    const BBox prediction = predicted(timestamp_ms);
    const float measured_cx = (measurement.x1 + measurement.x2) * 0.5F;
    const float measured_cy = (measurement.y1 + measurement.y2) * 0.5F;
    const float measured_w = measurement.x2 - measurement.x1;
    const float measured_h = measurement.y2 - measurement.y1;
    const float elapsed = std::max(
        0.001F, static_cast<float>(std::max<std::int64_t>(1, timestamp_ms - last_update_ms)) / 1000.0F);
    const float predicted_cx = (prediction.x1 + prediction.x2) * 0.5F;
    const float predicted_cy = (prediction.y1 + prediction.y2) * 0.5F;
    const float predicted_w = prediction.x2 - prediction.x1;
    const float predicted_h = prediction.y2 - prediction.y1;
    constexpr float position_gain = 0.70F;
    constexpr float velocity_gain = 0.22F;
    vx_ += velocity_gain * ((measured_cx - predicted_cx) / elapsed);
    vy_ += velocity_gain * ((measured_cy - predicted_cy) / elapsed);
    vw_ += velocity_gain * ((measured_w - predicted_w) / elapsed);
    vh_ += velocity_gain * ((measured_h - predicted_h) / elapsed);
    cx_ = predicted_cx + position_gain * (measured_cx - predicted_cx);
    cy_ = predicted_cy + position_gain * (measured_cy - predicted_cy);
    width_ = std::max(kMinimumSize, predicted_w + position_gain * (measured_w - predicted_w));
    height_ = std::max(kMinimumSize, predicted_h + position_gain * (measured_h - predicted_h));
    last_measurement_ms = timestamp_ms;
    last_update_ms = timestamp_ms;
}

bool SingleDeviceTracker::plausible(const BBox& measurement, const BBox& prediction) const {
    return bbox_iou(measurement, prediction) >= config_.min_iou
        || center_distance(measurement, prediction) <= diagonal(prediction) * config_.max_center_shift_ratio;
}

std::string to_string(TrackState state) {
    switch (state) {
    case TrackState::NoTarget: return "NO_TARGET";
    case TrackState::Tracking: return "TRACKING";
    case TrackState::Holding: return "HOLDING";
    case TrackState::Lost: return "LOST";
    }
    return "UNKNOWN";
}

}  // namespace medvision
