std::vector<Point2f> FaceLandmarker::detect_rgb(
    const std::uint8_t* pixels,
    int width,
    int height,
    std::size_t byte_count) {
    if (pixels == nullptr || width <= 0 || height <= 0) {
        throw std::invalid_argument("face input image is empty");
    }
    if (byte_count != static_cast<std::size_t>(width) * static_cast<std::size_t>(height) * 3U
        || byte_count > static_cast<std::size_t>(std::numeric_limits<int>::max())) {
        throw std::invalid_argument("face input must be tightly packed RGB");
    }

    MpImagePtr image{};
    char* error = nullptr;
    auto status = MpImageCreateFromUint8Data(
        kMpImageFormatSrgb,
        width,
        height,
        pixels,
        static_cast<int>(byte_count),
        &image,
        &error);
    if (status != kMpOk) {
        throw media_pipe_error("MpImageCreateFromUint8Data", status, error);
    }

    FaceLandmarkerResult result{};
    error = nullptr;
    status = MpFaceLandmarkerDetectImage(impl_->handle, image, nullptr, &result, &error);
    MpImageFree(image);
    if (status != kMpOk) {
        throw media_pipe_error("MpFaceLandmarkerDetectImage", status, error);
    }

    std::vector<Point2f> landmarks;
    if (result.face_landmarks_count > 0 && result.face_landmarks != nullptr) {
        const auto& face = result.face_landmarks[0];
        landmarks.reserve(face.landmarks_count);
        for (std::uint32_t index = 0; index < face.landmarks_count; ++index) {
            landmarks.push_back({
                face.landmarks[index].x * static_cast<float>(width),
                face.landmarks[index].y * static_cast<float>(height),
            });
        }
    }
    MpFaceLandmarkerCloseResult(&result);
    return landmarks;
}

