Json percentile_json(const std::vector<double>& values, double fraction) {
    if (values.empty()) return nullptr;
    auto ordered = values;
    std::sort(ordered.begin(), ordered.end());
    const auto index = static_cast<std::size_t>(std::clamp(
        std::ceil(fraction * static_cast<double>(ordered.size())) - 1.0, 0.0, static_cast<double>(ordered.size() - 1)));
    return ordered[index];
}

Json metrics_json(const StreamSession& session) {
    const auto& metrics = session.metrics;
    const double fps = metrics.total_latency_ms.empty() ? 0.0 : 1000.0 * static_cast<double>(metrics.total_latency_ms.size()) /
        std::accumulate(metrics.total_latency_ms.begin(), metrics.total_latency_ms.end(), 0.0);
    return {{"session_id", session.id}, {"stopped", session.stopped},
            {"processed_frames", metrics.processed_frames}, {"detection_frames", metrics.detection_frames},
            {"holding_frames", metrics.holding_frames}, {"lost_frames", metrics.lost_frames},
            {"reacquisition_count", metrics.reacquisition_count}, {"contact_valid_frames", metrics.contact_valid_frames},
            {"average_fps", fps}, {"p50_total_server_ms", percentile_json(metrics.total_latency_ms, 0.50)},
            {"p95_total_server_ms", percentile_json(metrics.total_latency_ms, 0.95)},
            {"p50_previous_round_trip_ms", percentile_json(metrics.previous_round_trip_ms, 0.50)}};
}

void write_metrics(const StreamSession& session) {
    std::ofstream output(session.output_dir / "stream_metrics.json");
    if (!output) throw std::runtime_error("cannot write stream metrics");
    output << metrics_json(session).dump(2) << '\n';
}

