    std::lock_guard<std::mutex> lock(registry.mutex);
    const auto found = registry.sessions.find(id);
    if (found == registry.sessions.end()) throw std::invalid_argument("unknown session_id");
    return found->second;
}

void stop_session(StreamSession& session) {
    if (session.stopped) return;
    session.stopped = true;
    if (session.jsonl.is_open()) { session.jsonl.flush(); session.jsonl.close(); }
    write_metrics(session);
}

Json stream_response_json(const StreamSession& session, const medvision::FrameResult& raw,
                          const medvision::TrackerUpdate& update, const medvision::ContactEstimate& contact,
                          double tracker_ms, double contact_ms, double total_ms, std::int64_t receive_ms,
                          const std::vector<std::string>& reasons, std::optional<double> previous_rtt) {
    Json raw_point = nullptr;
    if (raw.contact.point.has_value()) raw_point = point_json(*raw.contact.point);
    Json contact_point = nullptr;
    if (contact.point.has_value()) contact_point = point_json(*contact.point);
    return {{"ok", true}, {"result", {
        {"session_id", session.id}, {"frame_id", raw.frame_id}, {"capture_timestamp_ms", raw.timestamp_ms},
        {"server_receive_timestamp_ms", receive_ms}, {"image_width", raw.image_width}, {"image_height", raw.image_height},
        {"face_detected", raw.face_detected}, {"face_bbox", optional_bbox_json(raw.face_roi)},
        {"raw_device", device_json(raw.device)}, {"device_bbox", optional_bbox_json(update.bbox)},
        {"device_score", raw.device.has_value() ? Json(raw.device->score) : Json(nullptr)},
        {"raw_detection_found", update.raw_detection_found}, {"track_state", medvision::to_string(update.state)},
        {"stale", update.stale}, {"tracker_prediction_used", update.prediction_used},
        {"raw_contact_point", raw_point}, {"contact_point", contact_point},
        {"contact_visibility", medvision::to_string(contact.visibility)}, {"contact_confidence", contact.confidence},
        {"needs_review", !reasons.empty()}, {"review_reasons", reasons},
        {"decode_ms", raw.timings.decode_ms}, {"detector_ms", raw.timings.detector_ms},
        {"tracker_ms", tracker_ms}, {"contact_ms", contact_ms}, {"total_server_ms", total_ms},
        {"round_trip_ms", previous_rtt.has_value() ? Json(*previous_rtt) : Json(nullptr)},
        {"model_ids", {{"device", raw.detector_version}, {"contact", raw.contact_version}}}
    }}};
}

Json marker_json(const std::vector<medvision::MarkerDetectionResult>& markers,
                 const medvision::MarkerDeviceEstimate& estimate) {
    Json values = Json::array();
    for (const auto& marker : markers) {
        Json corners = Json::array();
        for (const auto& point : marker.corners) corners.push_back(Json::array({point.x, point.y}));
        values.push_back({{"marker_id", marker.marker_id}, {"corners", corners},
                          {"center", Json::array({marker.center.x, marker.center.y})},
                          {"side_length_px", marker.side_length_px}, {"rotation_deg", marker.rotation_deg},
                          {"confidence", marker.confidence}});
    }
    return {{"marker_detected", estimate.marker_detected}, {"visible_marker_ids", estimate.visible_marker_ids},
            {"markers", values}, {"single_marker_fallback", estimate.single_marker_fallback},
            {"source", estimate.source}, {"device_orientation", estimate.marker_detected ? Json(estimate.orientation_deg) : Json(nullptr)},
            {"detection_confidence", estimate.marker_detected ? Json(estimate.confidence) : Json(nullptr)}};
}

Json marker_stream_response(const StreamSession& session, const medvision::MarkerDeviceEstimate& estimate,
                            const std::vector<medvision::MarkerDetectionResult>& markers,
                            const medvision::TrackerUpdate& update, int width, int height,
                            std::int64_t frame_id, std::int64_t capture_ms, double total_ms,
                            const std::vector<std::string>& reasons) {
    Json head = nullptr;
    std::string head_status = "not_annotatable";
    if (update.state == medvision::TrackState::Tracking && update.detection_accepted && estimate.treatment_head_point.has_value()) {
        head = Json::array({estimate.treatment_head_point->x, estimate.treatment_head_point->y});
        head_status = estimate.single_marker_fallback ? "estimated" : "visible";
    }
    Json marker = marker_json(markers, estimate);
    return {{"ok", true}, {"result", {
        {"session_id", session.id}, {"frame_id", frame_id}, {"capture_timestamp_ms", capture_ms},
        {"image_width", width}, {"image_height", height}, {"mode", "marker_only"},
        {"marker_detected", marker.at("marker_detected")}, {"visible_marker_ids", marker.at("visible_marker_ids")},
        {"markers", marker.at("markers")}, {"single_marker_fallback", marker.at("single_marker_fallback")},
        {"marker_source", marker.at("source")}, {"device_bbox", optional_bbox_json(update.bbox)},
        {"device_orientation", marker.at("device_orientation")}, {"treatment_head_point", head},
        {"treatment_head_status", head_status}, {"track_state", medvision::to_string(update.state)},
        {"stale", update.stale}, {"detection_confidence", marker.at("detection_confidence")},
        {"needs_review", !reasons.empty()}, {"review_reasons", reasons}, {"total_server_ms", total_ms}
    }}};
}
void write_binary(const fs::path& path, const std::vector<std::uint8_t>& bytes) {
    std::ofstream output(path, std::ios::binary);
    if (!output) throw std::runtime_error("cannot write annotated image");
    output.write(reinterpret_cast<const char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
    if (!output) throw std::runtime_error("failed while writing annotated image");
}

