    require(queue.dropped() == 1, "bounded queue drop count");
    require(queue.wait_pop() == 2 && queue.wait_pop() == 3, "bounded queue keeps newest frames");
    queue.close();
    require(!queue.wait_pop().has_value(), "closed queue returns empty");

    std::cout << "MEDVISION_CORE_TESTS=PASS\n";
    return EXIT_SUCCESS;
