namespace medvision {

FaceRegionResult classify_face_region(Point2f contact, const FaceGeometry& face) {
    if (!face.valid || face.face_hull.size() < 3) {
        return {FaceRegion::Unknown, 0.0F};
    }
    if (!point_in_polygon(contact, face.face_hull)) {
        return {FaceRegion::OutsideFace, 1.0F};
    }
    for (const auto& region : face.regions) {
        if (point_in_polygon(contact, region.points)) {
            return {region.region, 1.0F};
        }
    }
    return {FaceRegion::Unknown, 0.0F};
}

std::string to_string(FaceRegion region) {
    switch (region) {
        case FaceRegion::Forehead: return "forehead";
        case FaceRegion::SubjectLeftCheek: return "subject_left_cheek";
        case FaceRegion::SubjectRightCheek: return "subject_right_cheek";
        case FaceRegion::NoseArea: return "nose_area";
        case FaceRegion::MouthChin: return "mouth_chin";
        case FaceRegion::Jawline: return "jawline";
        case FaceRegion::OutsideFace: return "outside_face";
        case FaceRegion::Unknown: return "unknown";
    }
    return "unknown";
}

std::string to_string(ContactVisibility visibility) {
    switch (visibility) {
        case ContactVisibility::Visible: return "visible";
        case ContactVisibility::OccludedInferable: return "occluded_inferable";
        case ContactVisibility::NotAnnotatable: return "not_annotatable";
    }
    return "not_annotatable";
}

