FrameResult ImagePipeline::infer(
    const std::vector<std::uint8_t>& encoded_image,
    std::uint64_t frame_id,
    std::int64_t timestamp_ms,
    bool infer_contact) {
    std::lock_guard<std::mutex> lock(impl_->inference_mutex);
    const auto total_started = Clock::now();
    FrameResult result;
    result.frame_id = frame_id;
    result.timestamp_ms = timestamp_ms;
    result.detector_version = impl_->config.detector_version;
    result.contact_version = impl_->config.contact_version;
    result.face_version = impl_->config.face_version;
    result.inference_provider = provider();

    auto started = Clock::now();
    const cv::Mat encoded(1, static_cast<int>(encoded_image.size()), CV_8UC1, const_cast<std::uint8_t*>(encoded_image.data()));
    const cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
    if (bgr.empty()) {
        throw std::invalid_argument("request body is not a valid JPEG or PNG image");
    }
    result.image_width = bgr.cols;
    result.image_height = bgr.rows;
    result.timings.decode_ms = elapsed_ms(started);

    started = Clock::now();
    cv::Mat rgb;
    cv::cvtColor(bgr, rgb, cv::COLOR_BGR2RGB);
    if (!rgb.isContinuous()) {
        rgb = rgb.clone();
    }
    const auto landmarks = impl_->face.detect_rgb(
        rgb.ptr<std::uint8_t>(),
        rgb.cols,
        rgb.rows,
        rgb.total() * rgb.elemSize());
    const auto gate = build_face_gate(landmarks, bgr.cols, bgr.rows);
    result.face_detected = gate.has_value();
    if (gate.has_value()) {
        result.face_roi = gate->search_roi;
    }
    result.timings.face_ms = elapsed_ms(started);

    std::size_t detector_candidate_count{};
    std::size_t rejected_candidate_count{};
    started = Clock::now();
    {
        LetterboxTransform transform;
        const auto outputs = impl_->detector.run(detector_input(bgr, transform));
        if (outputs.empty() || outputs.front().values.size() % 6U != 0U) {
            throw std::runtime_error("unexpected YOLOX output");
        }
        std::vector<YoloXPrediction> predictions;
        predictions.reserve(outputs.front().values.size() / 6U);
        const auto& values = outputs.front().values;
        for (std::size_t offset = 0; offset < values.size(); offset += 6U) {
            predictions.push_back({
                values[offset],
                values[offset + 1],
                values[offset + 2],
                values[offset + 3],
                values[offset + 4],
                values[offset + 5],
            });
        }
        const auto candidates = decode_yolox(
            predictions,
            impl_->config.detection_confidence,
            impl_->config.nms_iou,
            transform);
        detector_candidate_count = candidates.size();
        std::vector<DeviceDetection> accepted;
        for (const auto& candidate : candidates) {
            if (!gate.has_value() || device_near_face(candidate.bbox, *gate)) {
                accepted.push_back(candidate);
            }
        }
        rejected_candidate_count = candidates.size() - accepted.size();
        if (!accepted.empty()) {
            auto selected = accepted.front();
            selected.candidate_count = accepted.size();
            selected.rejected_candidate_count = rejected_candidate_count;
            result.device = selected;
        }
    }
    result.timings.detector_ms = elapsed_ms(started);

    started = Clock::now();
    result.contact.visibility = ContactVisibility::NotAnnotatable;
    result.contact.confidence = 1.0F;
    if (infer_contact && result.device.has_value() && gate.has_value()) {
        const BBox roi = expanded_roi(
            result.device->bbox,
            bgr.cols,
            bgr.rows,
            impl_->config.contact_roi_expansion);
        result.contact.roi = roi;
        const auto outputs = impl_->contact.run(contact_input(bgr, roi));
        const Tensor* heatmap = nullptr;
        const Tensor* visibility = nullptr;
        for (const auto& output : outputs) {
            if (output.values.size() == 64U * 64U) {
                heatmap = &output;
            } else if (output.values.size() == 3U) {
                visibility = &output;
            }
        }
        if (heatmap == nullptr || visibility == nullptr) {
            throw std::runtime_error("unexpected contact model outputs");
        }
        const auto probabilities = softmax(visibility->values);
        const auto best = static_cast<std::size_t>(
            std::distance(probabilities.begin(), std::max_element(probabilities.begin(), probabilities.end())));
        result.contact.visibility = visibility_from_index(best);
        result.contact.confidence = probabilities[best];
        result.contact.heatmap_confidence = heatmap_confidence(heatmap->values);
        if (result.contact.visibility != ContactVisibility::NotAnnotatable) {
            const auto point = decode_heatmap_peak_neighborhood(heatmap->values, 64, 64, roi, 3);
            if (contact_near_face(point, *gate)) {
                result.contact.point = point;
            } else {
                result.contact.visibility = ContactVisibility::NotAnnotatable;
                result.contact.point.reset();
                result.contact.gate_rejected = true;
            }
        }
    }
    result.timings.contact_ms = elapsed_ms(started);

    if (!result.face_detected) {
        result.review_reasons.emplace_back("face_not_detected");
    }
    if (!result.device.has_value()) {
        result.review_reasons.emplace_back("device_not_detected");
    }
    if (rejected_candidate_count > 0) {
        result.review_reasons.emplace_back("device_candidates_rejected_by_face_gate");
    }
    if (detector_candidate_count > 1) {
        result.review_reasons.emplace_back("multiple_device_candidates");
    }
    if (result.contact.visibility == ContactVisibility::NotAnnotatable) {
        result.review_reasons.emplace_back("contact_not_annotatable");
    }
    if (result.contact.gate_rejected) {
        result.review_reasons.emplace_back("contact_outside_face_gate");
    }
    if (result.contact.point.has_value()
        && result.contact.heatmap_confidence < impl_->config.low_heatmap_confidence) {
        result.review_reasons.emplace_back("low_contact_heatmap_confidence");
    }
    result.needs_review = !result.review_reasons.empty();
    result.contact.needs_review = result.needs_review;
    result.timings.total_ms = elapsed_ms(total_started);
    return result;
}

ContactEstimate ImagePipeline::infer_contact_for_device(
    const std::vector<std::uint8_t>& encoded_image,
    const BBox& device_bbox) {
    std::lock_guard<std::mutex> lock(impl_->inference_mutex);
    ContactEstimate result;
    result.visibility = ContactVisibility::NotAnnotatable;
    result.needs_review = true;
    const cv::Mat encoded(
        1, static_cast<int>(encoded_image.size()), CV_8UC1,
        const_cast<std::uint8_t*>(encoded_image.data()));
    const cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
    if (bgr.empty()) {
        throw std::invalid_argument("request body is not a valid JPEG or PNG image");
    }
    if (!std::isfinite(device_bbox.x1) || !std::isfinite(device_bbox.y1)
        || !std::isfinite(device_bbox.x2) || !std::isfinite(device_bbox.y2)
        || device_bbox.x1 < 0.0F || device_bbox.y1 < 0.0F
        || device_bbox.x2 > static_cast<float>(bgr.cols) || device_bbox.y2 > static_cast<float>(bgr.rows)
        || device_bbox.x2 - device_bbox.x1 < 2.0F || device_bbox.y2 - device_bbox.y1 < 2.0F) {
        return result;
    }
    cv::Mat rgb;
    cv::cvtColor(bgr, rgb, cv::COLOR_BGR2RGB);
    if (!rgb.isContinuous()) {
        rgb = rgb.clone();
    }
    const auto landmarks = impl_->face.detect_rgb(
        rgb.ptr<std::uint8_t>(), rgb.cols, rgb.rows, rgb.total() * rgb.elemSize());
    const auto gate = build_face_gate(landmarks, bgr.cols, bgr.rows);
    if (!gate.has_value()) {
        return result;
    }
    const BBox roi = expanded_roi(device_bbox, bgr.cols, bgr.rows, impl_->config.contact_roi_expansion);
    result.roi = roi;
    const auto outputs = impl_->contact.run(contact_input(bgr, roi));
    const Tensor* heatmap = nullptr;
    const Tensor* visibility = nullptr;
    for (const auto& output : outputs) {
        if (output.values.size() == 64U * 64U) {
            heatmap = &output;
        } else if (output.values.size() == 3U) {
            visibility = &output;
        }
    }
    if (heatmap == nullptr || visibility == nullptr) {
        throw std::runtime_error("unexpected contact model outputs");
    }
    const auto probabilities = softmax(visibility->values);
    const auto best = static_cast<std::size_t>(
        std::distance(probabilities.begin(), std::max_element(probabilities.begin(), probabilities.end())));
    result.visibility = visibility_from_index(best);
    result.confidence = probabilities[best];
    result.heatmap_confidence = heatmap_confidence(heatmap->values);
    if (result.visibility != ContactVisibility::NotAnnotatable) {
        const auto point = decode_heatmap_peak_neighborhood(heatmap->values, 64, 64, roi, 3);
        if (contact_near_face(point, *gate)) {
            result.point = point;
        } else {
            result.visibility = ContactVisibility::NotAnnotatable;
            result.gate_rejected = true;
        }
    }
    result.needs_review = !result.point.has_value()
        || result.heatmap_confidence < impl_->config.low_heatmap_confidence;
    return result;
}
