    {FaceRegion::NoseArea, {{168, 351, 419, 248, 281, 275, 4, 45, 51, 3, 196, 122}}},
    {FaceRegion::Forehead, {{109, 10, 338, 297, 332, 284, 251, 389, 356, 264, 368, 300,
                             293, 334, 296, 336, 107, 66, 105, 63, 70, 139, 156, 162, 21,
