std::vector<Point2f> polygon(const std::vector<Point2f>& landmarks, const Indices& indices) {
    std::vector<Point2f> result;
    result.reserve(indices.size());
    for (const int index : indices) {
        if (index < 0 || static_cast<std::size_t>(index) >= landmarks.size()) {
            return {};
        }
        result.push_back(landmarks[static_cast<std::size_t>(index)]);
    }
    return result;
}

Point2f nearest_on_segment(Point2f point, Point2f left, Point2f right) {
    const float dx = right.x - left.x;
    const float dy = right.y - left.y;
    const float length = dx * dx + dy * dy;
    if (length <= 1e-12F) {
        return left;
    }
    const float factor = std::clamp(
        ((point.x - left.x) * dx + (point.y - left.y) * dy) / length, 0.0F, 1.0F);
    return {left.x + factor * dx, left.y + factor * dy};
}

float distance(Point2f left, Point2f right) {
    return std::hypot(left.x - right.x, left.y - right.y);
}

Point2f nearest_on_polygon(Point2f point, const std::vector<Point2f>& values) {
    Point2f best{};
    float best_distance = std::numeric_limits<float>::infinity();
    for (std::size_t index = 0; index < values.size(); ++index) {
        const Point2f candidate =
            nearest_on_segment(point, values[index], values[(index + 1) % values.size()]);
        const float current = distance(point, candidate);
        if (current < best_distance) {
            best = candidate;
            best_distance = current;
        }
    }
    return best;
}

FaceRegion classify(Point2f point, const std::vector<Point2f>& landmarks) {
    for (const auto& [region, polygons] : kRegions) {
        for (const auto& indices : polygons) {
            const auto values = polygon(landmarks, indices);
            if (point_in_polygon(point, values)) {
                return region;
            }
        }
    }
    return point_in_polygon(point, polygon(landmarks, kFaceOval))
        ? FaceRegion::Unknown : FaceRegion::OutsideFace;
}

std::optional<Point2f> local_coordinates(Point2f point, const std::vector<Point2f>& landmarks) {
    if (landmarks.size() <= 454) {
        return std::nullopt;
    }
    const Point2f top = landmarks[10];
    const Point2f chin = landmarks[152];
    const Point2f subject_right = landmarks[234];
    const Point2f subject_left = landmarks[454];
    const float vx = chin.x - top.x;
    const float vy = chin.y - top.y;
    const float height = std::hypot(vx, vy);
    const float width = distance(subject_left, subject_right);
    if (height < 10.0F || width < 10.0F) {
        return std::nullopt;
    }
    const float vertical_x = vx / height;
    const float vertical_y = vy / height;
    float horizontal_x = -vertical_y;
    float horizontal_y = vertical_x;
    const float edge_x = subject_left.x - subject_right.x;
    const float edge_y = subject_left.y - subject_right.y;
    if (horizontal_x * edge_x + horizontal_y * edge_y < 0.0F) {
        horizontal_x = -horizontal_x;
        horizontal_y = -horizontal_y;
    }
    const float offset_x = point.x - top.x;
    const float offset_y = point.y - top.y;
    return Point2f{
        (offset_x * horizontal_x + offset_y * horizontal_y) / width,
        (offset_x * vertical_x + offset_y * vertical_y) / height,
    };
}

std::optional<std::pair<std::array<int, 3>, std::array<float, 3>>> nearest_triangle(
    Point2f point,
    const std::vector<Point2f>& landmarks,
    int width,
    int height) {
    cv::Subdiv2D subdiv(cv::Rect(0, 0, width, height));
    const std::size_t count = std::min<std::size_t>(468, landmarks.size());
    for (std::size_t index = 0; index < count; ++index) {
        const auto& value = landmarks[index];
        if (value.x >= 0.0F && value.y >= 0.0F
            && value.x < static_cast<float>(width) && value.y < static_cast<float>(height)) {
            try {
                subdiv.insert({value.x, value.y});
            } catch (const cv::Exception&) {
            }
        }
    }
    std::vector<cv::Vec6f> raw_triangles;
    subdiv.getTriangleList(raw_triangles);
    float best_penalty = std::numeric_limits<float>::infinity();
    std::optional<std::pair<std::array<int, 3>, std::array<float, 3>>> best;
    std::set<std::array<int, 3>> visited;
    for (const auto& raw : raw_triangles) {
        std::array<int, 3> indices{};
        bool mapped = true;
        for (int vertex = 0; vertex < 3; ++vertex) {
            const Point2f candidate{raw[vertex * 2], raw[vertex * 2 + 1]};
            float nearest_distance = std::numeric_limits<float>::infinity();
            int nearest_index = -1;
            for (std::size_t index = 0; index < count; ++index) {
                const float current = distance(candidate, landmarks[index]);
                if (current < nearest_distance) {
                    nearest_distance = current;
                    nearest_index = static_cast<int>(index);
                }
            }
            if (nearest_index < 0 || nearest_distance > 2.5F) {
                mapped = false;
                break;
            }
            indices[vertex] = nearest_index;
        }
        std::sort(indices.begin(), indices.end());
        if (!mapped || indices[0] == indices[1] || indices[1] == indices[2]
            || !visited.insert(indices).second) {
            continue;
        }
        const auto& a = landmarks[static_cast<std::size_t>(indices[0])];
        const auto& b = landmarks[static_cast<std::size_t>(indices[1])];
        const auto& c = landmarks[static_cast<std::size_t>(indices[2])];
        const float denominator =
            (b.y - c.y) * (a.x - c.x) + (c.x - b.x) * (a.y - c.y);
        if (std::abs(denominator) < 1e-9F) {
            continue;
        }
        const float first =
            ((b.y - c.y) * (point.x - c.x) + (c.x - b.x) * (point.y - c.y)) / denominator;
        const float second =
            ((c.y - a.y) * (point.x - c.x) + (a.x - c.x) * (point.y - c.y)) / denominator;
        const float third = 1.0F - first - second;
        const float penalty =
            std::max(0.0F, -first) + std::max(0.0F, -second) + std::max(0.0F, -third);
        if (penalty < best_penalty) {
            best_penalty = penalty;
            best = std::make_pair(indices, std::array<float, 3>{first, second, third});
        }
        if (penalty <= 1e-5F) {
            break;
        }
    }
    return best;
}

