FaceMeshProjection project_to_face_mesh(
    Point2f point,
    const std::vector<Point2f>& landmarks,
    int image_width,
    int image_height,
    float max_distance_ratio) {
    FaceMeshProjection result;
    result.landmark_count = landmarks.size();
    if (landmarks.size() <= 454 || image_width <= 0 || image_height <= 0) {
        return result;
    }
    const auto face_oval = polygon(landmarks, kFaceOval);
    const bool inside = point_in_polygon(point, face_oval);
    const Point2f snapped = inside ? point : nearest_on_polygon(point, face_oval);
    const float face_width = distance(landmarks[234], landmarks[454]);
    const float face_height = distance(landmarks[10], landmarks[152]);
    const float diagonal = std::max(1.0F, std::hypot(face_width, face_height));
    result.distance_ratio = inside ? 0.0F : distance(point, snapped) / diagonal;
    result.mesh_uv = local_coordinates(inside ? point : snapped, landmarks);
    if (result.distance_ratio > max_distance_ratio) {
        return result;
    }
    result.point = snapped;
    result.region = classify(snapped, landmarks);
    result.confidence = std::clamp(1.0F - result.distance_ratio / max_distance_ratio, 0.0F, 1.0F);
    result.accepted = true;
    if (const auto triangle = nearest_triangle(
            snapped, landmarks, image_width, image_height); triangle.has_value()) {
        std::ostringstream id;
        id << triangle->first[0] << '-' << triangle->first[1] << '-' << triangle->first[2];
        result.triangle_id = id.str();
    }
    return result;
}

std::string face_region_label_zh(FaceRegion region) {
    switch (region) {
    case FaceRegion::Forehead: return "额头";
    case FaceRegion::SubjectLeftCheek: return "本人左脸颊";
    case FaceRegion::SubjectRightCheek: return "本人右脸颊";
    case FaceRegion::NoseArea: return "鼻部";
    case FaceRegion::MouthChin: return "口唇/下巴";
    case FaceRegion::Jawline: return "下颌线";
    case FaceRegion::OutsideFace: return "脸外";
    case FaceRegion::Unknown: return "未知";
    }
    return "未知";
}

std::string to_string(RuntimeState state) {
    switch (state) {
    case RuntimeState::Searching: return "SEARCHING";
    case RuntimeState::Tracking: return "TRACKING";
    case RuntimeState::Uncertain: return "UNCERTAIN";
    case RuntimeState::Lost: return "LOST";
    }
    return "SEARCHING";
}

std::string to_string(BBoxSource source) {
    switch (source) {
    case BBoxSource::None: return "none";
    case BBoxSource::YoloX: return "yolox";
    case BBoxSource::OpticalFlow: return "optical_flow";
    }
    return "none";
}

