const source=`#include "medvision/runtime.hpp"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <limits>
#include <mutex>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>

#include <opencv2/imgproc.hpp>
#include <opencv2/video/tracking.hpp>

#include "medvision/geometry.hpp"

namespace medvision {
namespace {

using Clock = std::chrono::steady_clock;

double elapsed_ms(Clock::time_point start) {
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

bool valid_bbox(const BBox& box, int width, int height) {
    return std::isfinite(box.x1) && std::isfinite(box.y1)
        && std::isfinite(box.x2) && std::isfinite(box.y2)
        && box.x1 >= 0.0F && box.y1 >= 0.0F
        && box.x2 <= static_cast<float>(width - 1)
        && box.y2 <= static_cast<float>(height - 1)
        && box.x2 - box.x1 >= 4.0F && box.y2 - box.y1 >= 4.0F;
}

Point2f center(const BBox& box) {
    return {(box.x1 + box.x2) * 0.5F, (box.y1 + box.y2) * 0.5F};
}

float diagonal(const BBox& box) {
    return std::max(1.0F, std::hypot(box.x2 - box.x1, box.y2 - box.y1));
}

float center_distance(const BBox& left, const BBox& right) {
    const auto a = center(left);
    const auto b = center(right);
    return std::hypot(a.x - b.x, a.y - b.y);
}

bool plausible(
    const BBox& measurement,
    const BBox& prediction,
    float minimum_iou,
    float maximum_center_shift_ratio) {
    return bbox_iou(measurement, prediction) >= minimum_iou
        || center_distance(measurement, prediction)
            <= diagonal(prediction) * maximum_center_shift_ratio;
}

float median(std::vector<float> values) {
    if (values.empty()) {
        return 0.0F;
    }
    const auto middle = values.begin() + static_cast<std::ptrdiff_t>(values.size() / 2U);
    std::nth_element(values.begin(), middle, values.end());
    float result = *middle;
    if (values.size() % 2U == 0U) {
        const auto lower = std::max_element(values.begin(), middle);
        result = (*lower + result) * 0.5F;
    }
    return result;
}

ContactEstimate empty_contact() {
    ContactEstimate result;
    result.visibility = ContactVisibility::NotAnnotatable;
    result.needs_review = true;
    return result;
}

}  // namespace

struct MedVisionRuntime::Impl {
    explicit Impl(std::shared_ptr<ImagePipeline> value, RuntimeConfig runtime_config)
        : pipeline(std::move(value)),
          config(runtime_config),
          kalman(8, 4, 0, CV_32F) {
        if (!pipeline) {
            throw std::invalid_argument("MedVisionRuntime requires an ImagePipeline");
        }
        kalman.measurementMatrix = cv::Mat::zeros(4, 8, CV_32F);
        for (int index = 0; index < 4; ++index) {
            kalman.measurementMatrix.at<float>(index, index) = 1.0F;
        }
        cv::setIdentity(kalman.processNoiseCov, cv::Scalar::all(1e-2));
        cv::setIdentity(kalman.measurementNoiseCov, cv::Scalar::all(2e-1));
        cv::setIdentity(kalman.errorCovPost, cv::Scalar::all(1.0));
        reset_unlocked();
    }

    std::shared_ptr<ImagePipeline> pipeline;
    RuntimeConfig config;
    mutable std::mutex mutex;
    RuntimeState runtime_state{RuntimeState::Searching};
    BBoxSource bbox_source{BBoxSource::None};
    cv::KalmanFilter kalman;
    bool kalman_initialized{};
    cv::Mat previous_gray;
    std::vector<cv::Point2f> previous_points;
    std::optional<BBox> tracked_bbox;
    std::optional<BBox> pending_candidate;
    int candidate_count{};
    std::uint64_t processed_index{};
    std::int64_t last_timestamp_ms{};
    std::int64_t last_detector_timestamp_ms{};
    std::int64_t last_contact_timestamp_ms{};
    float last_device_score{};
    ContactEstimate cached_contact{empty_contact()};
    FaceRegionResult cached_region;
    bool cached_face_detected{};
    std::optional<BBox> cached_face_roi;

    void reset_unlocked() {
        runtime_state = RuntimeState::Searching;
        bbox_source = BBoxSource::None;
        kalman_initialized = false;
        previous_gray.release();
        previous_points.clear();
        tracked_bbox.reset();
        pending_candidate.reset();
        candidate_count = 0;
        processed_index = 0;
        last_timestamp_ms = 0;
        last_detector_timestamp_ms = 0;
        last_contact_timestamp_ms = 0;
        last_device_score = 0.0F;
        cached_contact = empty_contact();
        cached_region = {};
        cached_face_detected = false;
        cached_face_roi.reset();
    }

    void configure_transition(float delta_seconds) {
        kalman.transitionMatrix = cv::Mat::eye(8, 8, CV_32F);
        for (int index = 0; index < 4; ++index) {
            kalman.transitionMatrix.at<float>(index, index + 4) = delta_seconds;
        }
    }

    BBox state_bbox(const cv::Mat& state, int width, int height) const {
        const float cx = state.at<float>(0);
        const float cy = state.at<float>(1);
        const float box_width = std::max(4.0F, state.at<float>(2));
        const float box_height = std::max(4.0F, state.at<float>(3));
        return clip_bbox(
            {cx - box_width * 0.5F, cy - box_height * 0.5F,
             cx + box_width * 0.5F, cy + box_height * 0.5F},
            width,
            height);
    }

    void initialize_kalman(const BBox& box) {
        const auto box_center = center(box);
        kalman.statePost = cv::Mat::zeros(8, 1, CV_32F);
        kalman.statePost.at<float>(0) = box_center.x;
        kalman.statePost.at<float>(1) = box_center.y;
        kalman.statePost.at<float>(2) = box.x2 - box.x1;
        kalman.statePost.at<float>(3) = box.y2 - box.y1;
        kalman.statePre = kalman.statePost.clone();
        cv::setIdentity(kalman.errorCovPost, cv::Scalar::all(1.0));
        kalman_initialized = true;
    }

    BBox predict_kalman(float delta_seconds, int width, int height) {
        configure_transition(delta_seconds);
        return state_bbox(kalman.predict(), width, height);
    }

    BBox correct_kalman(const BBox& box, int width, int height) {
        const auto box_center = center(box);
        cv::Mat measurement(4, 1, CV_32F);
        measurement.at<float>(0) = box_center.x;
        measurement.at<float>(1) = box_center.y;
        measurement.at<float>(2) = box.x2 - box.x1;
        measurement.at<float>(3) = box.y2 - box.y1;
        return state_bbox(kalman.correct(measurement), width, height);
    }

    void seed_flow(const cv::Mat& gray, const BBox& box) {
        cv::Mat mask(gray.size(), CV_8UC1, cv::Scalar(0));
        const BBox clipped = clip_bbox(box, gray.cols, gray.rows);
        const int x1 = std::max(0, static_cast<int>(std::floor(clipped.x1)));
        const int y1 = std::max(0, static_cast<int>(std::floor(clipped.y1)));
        const int x2 = std::min(gray.cols, static_cast<int>(std::ceil(clipped.x2)));
        const int y2 = std::min(gray.rows, static_cast<int>(std::ceil(clipped.y2)));
        if (x2 <= x1 || y2 <= y1) {
            previous_points.clear();
            return;
        }
        mask(cv::Rect(x1, y1, x2 - x1, y2 - y1)).setTo(255);
        cv::goodFeaturesToTrack(gray, previous_points, 80, 0.01, 4.0, mask, 3, false, 0.04);
    }

    std::optional<BBox> flow_update(
        const cv::Mat& gray,
        const BBox& prediction,
        double& duration_ms) {
        const auto started = Clock::now();
        if (previous_gray.empty()
            || previous_points.size() < static_cast<std::size_t>(config.minimum_flow_points)) {
            duration_ms = elapsed_ms(started);
            return std::nullopt;
        }
        std::vector<cv::Point2f> current_points;
        std::vector<unsigned char> status;
        std::vector<float> errors;
        cv::calcOpticalFlowPyrLK(
            previous_gray,
            gray,
            previous_points,
            current_points,
            status,
            errors,
            cv::Size(21, 21),
            3,
            cv::TermCriteria(
                cv::TermCriteria::COUNT | cv::TermCriteria::EPS, 30, 0.01),
            0,
            1e-4);
        std::vector<float> dx;
        std::vector<float> dy;
        std::vector<cv::Point2f> accepted;
        for (std::size_t index = 0; index < status.size(); ++index) {
            if (status[index] == 0 || !std::isfinite(errors[index])
                || errors[index] > config.maximum_flow_error) {
                continue;
            }
            dx.push_back(current_points[index].x - previous_points[index].x);
            dy.push_back(current_points[index].y - previous_points[index].y);
            accepted.push_back(current_points[index]);
        }
        duration_ms = elapsed_ms(started);
        if (accepted.size() < static_cast<std::size_t>(config.minimum_flow_points)) {
            return std::nullopt;
        }
        const float shift_x = median(dx);
        const float shift_y = median(dy);
        previous_points = std::move(accepted);
        return clip_bbox(
            {prediction.x1 + shift_x, prediction.y1 + shift_y,
             prediction.x2 + shift_x, prediction.y2 + shift_y},
            gray.cols,
            gray.rows);
    }

    void initialize_track(
        const BBox& box,
        float score,
        const cv::Mat& gray,
        std::int64_t timestamp_ms,
        bool reacquired) {
        initialize_kalman(box);
        tracked_bbox = box;
        last_device_score = score;
        last_detector_timestamp_ms = timestamp_ms;
        runtime_state = RuntimeState::Tracking;
        bbox_source = BBoxSource::YoloX;
        pending_candidate.reset();
        candidate_count = 0;
        cached_contact = empty_contact();
        last_contact_timestamp_ms = 0;
        seed_flow(gray, box);
        if (reacquired) {
            cached_region = {};
        }
    }

    void lose_track() {
        runtime_state = RuntimeState::Lost;
        bbox_source = BBoxSource::None;
        tracked_bbox.reset();
        previous_points.clear();
        kalman_initialized = false;
        cached_contact = empty_contact();
        cached_region = {};
        cached_face_detected = false;
        cached_face_roi.reset();
        last_contact_timestamp_ms = 0;
        pending_candidate.reset();
        candidate_count = 0;
    }
};

MedVisionRuntime::MedVisionRuntime(
    std::shared_ptr<ImagePipeline> pipeline,
    RuntimeConfig config)
    : impl_(std::make_unique<Impl>(std::move(pipeline), config)) {}

MedVisionRuntime::~MedVisionRuntime() = default;
MedVisionRuntime::MedVisionRuntime(MedVisionRuntime&&) noexcept = default;
MedVisionRuntime& MedVisionRuntime::operator=(MedVisionRuntime&&) noexcept = default;

FrameResult MedVisionRuntime::processFrame(
    const cv::Mat& bgr,
    std::int64_t frame_id,
    std::int64_t timestamp_ms) {
    if (bgr.empty() || bgr.type() != CV_8UC3) {
        throw std::invalid_argument("processFrame expects a non-empty CV_8UC3 frame");
    }
    std::lock_guard<std::mutex> lock(impl_->mutex);
    const auto total_started = Clock::now();
    ++impl_->processed_index;
    FrameResult result;
    result.frame_id = static_cast<std::uint64_t>(std::max<std::int64_t>(0, frame_id));
    result.timestamp_ms = timestamp_ms;
    result.image_width = bgr.cols;
    result.image_height = bgr.rows;
    result.detector_version = impl_->pipeline->config().detector_version;
    result.contact_version = impl_->pipeline->config().contact_version;
    result.face_version = impl_->pipeline->config().face_version;
    result.inference_provider = impl_->pipeline->provider();

    cv::Mat gray;
    cv::cvtColor(bgr, gray, cv::COLOR_BGR2GRAY);
    const float delta_seconds = impl_->last_timestamp_ms > 0
        ? std::clamp(
            static_cast<float>(timestamp_ms - impl_->last_timestamp_ms) / 1000.0F,
            0.001F,
            0.25F)
        : 1.0F / 30.0F;
    impl_->last_timestamp_ms = timestamp_ms;

    const bool was_lost = impl_->runtime_state == RuntimeState::Lost;
    bool detector_ran = false;
    bool detector_accepted = false;
    bool just_initialized = false;
    FrameResult detector_result;
    std::optional<BBox> prediction;
    if (impl_->kalman_initialized && impl_->tracked_bbox.has_value()) {
        prediction = impl_->predict_kalman(delta_seconds, bgr.cols, bgr.rows);
    }

    if ((impl_->runtime_state == RuntimeState::Tracking
         || impl_->runtime_state == RuntimeState::Uncertain)
        && prediction.has_value()) {
