        {"face_mesh_valid", value.face_region.mesh_valid},
        {"face_landmark_count", value.face_region.landmark_count},
        {"face_detected", value.face_detected},
        {"face_roi", optional_bbox(value.face_roi)},
        {"reacquired", value.reacquired},
        {"needs_review", value.needs_review},
        {"review_reasons", value.review_reasons},
        {"timings_ms", {
            {"decode", value.timings.decode_ms},
            {"face", value.timings.face_ms},
            {"device", value.timings.detector_ms},
