            {"contact", value.contact_version},
            {"face", value.face_version},
            {"provider", value.inference_provider},
        }},
    };
}

std::int64_t integer_header(
    const httplib::Request& request,
    const char* name,
    std::int64_t fallback) {
    const auto text = request.get_header_value(name);
    if (text.empty()) {
        return fallback;
    }
    std::size_t consumed{};
    const auto value = std::stoll(text, &consumed);
    if (consumed != text.size()) {
        throw std::invalid_argument(std::string("invalid ") + name);
    }
    return value;
}

Arguments parse_arguments(int argc, char** argv) {
    Arguments result;
    fs::path config_path;
    for (int index = 1; index < argc; ++index) {
        const std::string value = argv[index];
        if (value == "--config") {
            if (++index >= argc) {
                throw std::invalid_argument("missing value for --config");
            }
            config_path = argv[index];
        }
    }
    if (!config_path.empty()) {
        std::ifstream input(config_path);
        if (!input) {
            throw std::invalid_argument("cannot open config: " + config_path.string());
        }
        Json config;
        input >> config;
        const auto directory = fs::absolute(config_path).parent_path();
        const auto resolve = [&](const std::string& value) {
            const fs::path candidate(value);
            return (candidate.is_absolute() ? candidate : directory / candidate)
                .lexically_normal().string();
        };
        result.host = config.value("host", result.host);
        result.port = config.value("port", result.port);
        result.pipeline.detection_confidence =
            config.value("device_confidence", result.pipeline.detection_confidence);
        result.pipeline.nms_iou =
            config.value("nms_iou", result.pipeline.nms_iou);
        result.pipeline.contact_roi_expansion =
            config.value("contact_roi_expansion", result.pipeline.contact_roi_expansion);
        if (config.contains("models")) {
            const auto& models = config.at("models");
            result.pipeline.detector_model =
                resolve(models.at("device").get<std::string>());
            result.pipeline.contact_model =
                resolve(models.at("contact").get<std::string>());
            result.pipeline.face_model =
                resolve(models.at("face").get<std::string>());
        }
        if (config.contains("runtime")) {
            const auto& runtime = config.at("runtime");
            result.runtime.detector_interval_frames =
                runtime.value("detector_interval_frames", result.runtime.detector_interval_frames);
            result.runtime.contact_interval_frames =
                runtime.value("contact_interval_frames", result.runtime.contact_interval_frames);
            result.runtime.candidate_confirmation_frames =
                runtime.value("candidate_confirmation_frames", result.runtime.candidate_confirmation_frames);
            result.runtime.max_detector_age_ms =
                runtime.value("max_detector_age_ms", result.runtime.max_detector_age_ms);
            result.runtime.max_contact_age_ms =
                runtime.value("max_contact_age_ms", result.runtime.max_contact_age_ms);
        }
    }
    for (int index = 1; index < argc; ++index) {
        const std::string value = argv[index];
        auto next = [&]() -> std::string {
            if (++index >= argc) {
                throw std::invalid_argument("missing value for " + value);
            }
            return argv[index];
        };
        if (value == "--config") {
            ++index;
        } else if (value == "--host") {
            result.host = next();
        } else if (value == "--port") {
            result.port = std::stoi(next());
        } else if (value == "--detector") {
            result.pipeline.detector_model = next();
        } else if (value == "--contact") {
            result.pipeline.contact_model = next();
        } else if (value == "--face") {
            result.pipeline.face_model = next();
        } else {
            throw std::invalid_argument("unknown argument: " + value);
        }
    }
    if (result.host != "127.0.0.1") {
        throw std::invalid_argument("offline runtime must bind to 127.0.0.1");
    }
    if (result.pipeline.detector_model.empty()
        || result.pipeline.contact_model.empty()
        || result.pipeline.face_model.empty()) {
        throw std::invalid_argument("device, contact and face model paths are required");
    }
    return result;
}

struct FlagGuard {
    explicit FlagGuard(std::atomic_flag& value) : flag(value) {}
    ~FlagGuard() { flag.clear(); }
    std::atomic_flag& flag;
};

}  // namespace

int main(int argc, char** argv) {
    Arguments arguments;
    try {
        arguments = parse_arguments(argc, argv);
    } catch (const std::exception& error) {
        std::cerr << "ARGUMENT_ERROR=" << error.what() << '\\n';
        return EXIT_FAILURE;
    }

    std::shared_ptr<medvision::ImagePipeline> pipeline;
    std::shared_ptr<medvision::MedVisionRuntime> runtime;
    try {
        pipeline = std::make_shared<medvision::ImagePipeline>(arguments.pipeline);
        runtime = std::make_shared<medvision::MedVisionRuntime>(pipeline, arguments.runtime);
    } catch (const std::exception& error) {
        std::cerr << "MODEL_LOAD=FAIL error=" << error.what() << '\\n';
        return EXIT_FAILURE;
    }

    httplib::Server server;
    std::atomic_flag frame_in_flight = ATOMIC_FLAG_INIT;
    server.set_payload_max_length(kMaximumImageBytes);
    server.set_post_routing_handler([](
        const httplib::Request& request,
        httplib::Response& response) {
        const auto origin = request.get_header_value("Origin");
        if (origin == "http://127.0.0.1:8080"
            || origin == "http://localhost:8080") {
            response.set_header("Access-Control-Allow-Origin", origin);
            response.set_header("Vary", "Origin");
        }
    });
    server.Options(R"(/.*)", [](const httplib::Request&, httplib::Response& response) {
        response.set_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
        response.set_header(
            "Access-Control-Allow-Headers",
            "Content-Type, X-Frame-Id, X-Capture-Timestamp-Ms");
        response.status = 204;
    });
    server.Get("/", [](const httplib::Request&, httplib::Response& response) {
        response.set_content(
            std::string(medvision::web::kOfflineCameraPage),
            "text/html; charset=utf-8");
    });
    server.Get("/health", [pipeline, runtime](
        const httplib::Request&,
        httplib::Response& response) {
        write_json(response, 200, {
            {"ok", true},
            {"service", "medvision_cpp_offline_runtime"},
            {"runtime", "cpp20"},
            {"offline", true},
            {"python_required", false},
            {"frame_queue_capacity", 1},
            {"drop_policy", "reject_concurrent_keep_latest_at_client"},
            {"state", medvision::to_string(runtime->state())},
            {"provider", pipeline->provider()},
            {"models", {
                {"device", {
                    {"id", pipeline->config().detector_version},
                    {"sha256", kDetectorSha256},
                    {"loaded", true},
                }},
                {"contact", {
                    {"id", pipeline->config().contact_version},
                    {"sha256", kContactSha256},
                    {"loaded", true},
                }},
                {"face", {
                    {"id", pipeline->config().face_version},
                    {"sha256", kFaceSha256},
                    {"loaded", true},
                    {"landmark_count", 478},
                }},
            }},
        });
    });
    server.Post("/v1/infer/image", [pipeline](
        const httplib::Request& request,
        httplib::Response& response) {
        if (request.body.empty()) {
            write_json(response, 400, error_json("empty_image", "请求体必须包含JPEG或PNG图片"));
            return;
        }
        try {
            const std::vector<std::uint8_t> bytes(request.body.begin(), request.body.end());
            auto result = pipeline->infer(
                bytes,
                static_cast<std::uint64_t>(std::max<std::int64_t>(
                    0, integer_header(request, "X-Frame-Id", 0))),
                integer_header(request, "X-Capture-Timestamp-Ms", 0));
            result.state = result.device.has_value()
                ? medvision::RuntimeState::Tracking
                : medvision::RuntimeState::Searching;
            result.bbox_source = result.device.has_value()
                ? medvision::BBoxSource::YoloX
                : medvision::BBoxSource::None;
            write_json(response, 200, {{"ok", true}, {"result", result_json(result)}});
        } catch (const std::invalid_argument& error) {
            write_json(response, 400, error_json("invalid_image", error.what()));
        } catch (const std::exception& error) {
            write_json(response, 500, error_json("inference_failed", error.what()));
        }
    });
    server.Post("/v1/stream/start", [runtime](
        const httplib::Request&,
        httplib::Response& response) {
        runtime->reset();
        write_json(response, 200, {{"ok", true}, {"state", "SEARCHING"}});
    });
    server.Post("/v1/stream/reset", [runtime](
        const httplib::Request&,
        httplib::Response& response) {
        runtime->reset();
        write_json(response, 200, {{"ok", true}, {"state", "SEARCHING"}});
    });
    server.Post("/v1/stream/frame", [runtime, &frame_in_flight](
        const httplib::Request& request,
        httplib::Response& response) {
        if (frame_in_flight.test_and_set()) {
            write_json(
                response,
                429,
                error_json("frame_in_flight", "上一帧仍在处理，本帧已丢弃以避免延迟堆积"));
            return;
        }
        FlagGuard guard(frame_in_flight);
        try {
            if (request.body.empty()) {
                throw std::invalid_argument("JPEG帧为空");
            }
            const std::vector<std::uint8_t> bytes(request.body.begin(), request.body.end());
            const cv::Mat encoded(
                1,
                static_cast<int>(bytes.size()),
                CV_8UC1,
                const_cast<std::uint8_t*>(bytes.data()));
            const cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
            if (bgr.empty()) {
                throw std::invalid_argument("无法解码JPEG帧");
            }
            const auto frame_id = integer_header(request, "X-Frame-Id", 0);
            const auto timestamp_ms =
                integer_header(request, "X-Capture-Timestamp-Ms", frame_id * 33);
            const auto result = runtime->processFrame(
                bgr,
                frame_id,
                timestamp_ms);
            write_json(response, 200, {{"ok", true}, {"result", result_json(result)}});
        } catch (const std::invalid_argument& error) {
            write_json(response, 400, error_json("invalid_stream_frame", error.what()));
        } catch (const std::exception& error) {
            write_json(response, 500, error_json("stream_inference_failed", error.what()));
        }
    });

    std::cout << "MEDVISION_OFFLINE_HTTP_URL=http://"
              << arguments.host << ':' << arguments.port << '\\n';
    std::cout << "RUNTIME=CPP20 OFFLINE=true PYTHON_REQUIRED=false\\n";
    if (!server.listen(arguments.host, arguments.port)) {
        std::cerr << "HTTP_LISTEN=FAIL\\n";
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
