std::int64_t header_integer(
    const httplib::Request& request,
    const char* name,
    std::int64_t fallback) {
    const auto text = request.get_header_value(name);
    if (text.empty()) return fallback;
    std::size_t consumed{};
    const auto result = std::stoll(text, &consumed);
    if (consumed != text.size()) throw std::invalid_argument(std::string("invalid ") + name);
    return result;
}

Arguments parse(int argc, char** argv) {
    Arguments result;
    fs::path config_path;
    for (int index = 1; index < argc; ++index) {
        if (std::string(argv[index]) == "--config" && index + 1 < argc) {
            config_path = argv[++index];
        }
    }
    if (!config_path.empty()) {
        std::ifstream input(config_path);
        if (!input) throw std::invalid_argument("cannot open config: " + config_path.string());
        Json config; input >> config;
        const auto root = fs::absolute(config_path).parent_path();
        const auto resolve = [&](const std::string& text) {
            const fs::path value(text);
            return (value.is_absolute() ? value : root / value).lexically_normal().string();
        };
        result.host = config.value("host", result.host);
        result.port = config.value("port", result.port);
        result.pipeline.detection_confidence = config.value("device_confidence", 0.25F);
        result.pipeline.nms_iou = config.value("nms_iou", 0.65F);
        result.pipeline.contact_roi_expansion = config.value("contact_roi_expansion", 0.20F);
        const auto& models = config.at("models");
        result.pipeline.detector_model = resolve(models.at("device").get<std::string>());
        result.pipeline.contact_model = resolve(models.at("contact").get<std::string>());
        result.pipeline.face_model = resolve(models.at("face").get<std::string>());
        if (config.contains("runtime")) {
            const auto& runtime = config.at("runtime");
            result.runtime.detector_interval_frames = runtime.value("detector_interval_frames", 5);
            result.runtime.contact_interval_frames = runtime.value("contact_interval_frames", 3);
            result.runtime.candidate_confirmation_frames = runtime.value("candidate_confirmation_frames", 2);
            result.runtime.max_detector_age_ms = runtime.value("max_detector_age_ms", 250);
            result.runtime.max_contact_age_ms = runtime.value("max_contact_age_ms", 150);
        }
    }
    for (int index = 1; index < argc; ++index) {
        const std::string arg = argv[index];
        auto next = [&]() {
            if (++index >= argc) throw std::invalid_argument("missing argument for " + arg);
            return std::string(argv[index]);
        };
        if (arg == "--config") ++index;
        else if (arg == "--host") result.host = next();
        else if (arg == "--port") result.port = std::stoi(next());
        else if (arg == "--detector") result.pipeline.detector_model = next();
        else if (arg == "--contact") result.pipeline.contact_model = next();
        else if (arg == "--face") result.pipeline.face_model = next();
        else throw std::invalid_argument("unknown argument: " + arg);
    }
    if (result.host != "127.0.0.1") throw std::invalid_argument("service must bind to 127.0.0.1");
    if (result.pipeline.detector_model.empty() || result.pipeline.contact_model.empty()
        || result.pipeline.face_model.empty()) {
        throw std::invalid_argument("all three model paths are required");
    }
    return result;
}

struct FlagGuard {
    explicit FlagGuard(std::atomic_flag& value) : flag(value) {}
    ~FlagGuard() { flag.clear(); }
    std::atomic_flag& flag;
};
}  // namespace

int main(int argc, char** argv) {
    Arguments arguments;
    try {
        arguments = parse(argc, argv);
    } catch (const std::exception& exception) {
        std::cerr << "ARGUMENT_ERROR=" << exception.what() << '\\n';
        return EXIT_FAILURE;
    }
    std::shared_ptr<medvision::ImagePipeline> pipeline;
    std::shared_ptr<medvision::MedVisionRuntime> runtime;
    try {
        pipeline = std::make_shared<medvision::ImagePipeline>(arguments.pipeline);
        runtime = std::make_shared<medvision::MedVisionRuntime>(pipeline, arguments.runtime);
    } catch (const std::exception& exception) {
        std::cerr << "MODEL_LOAD=FAIL error=" << exception.what() << '\\n';
        return EXIT_FAILURE;
    }

    httplib::Server server;
    std::atomic_flag in_flight = ATOMIC_FLAG_INIT;
    server.set_payload_max_length(32U * 1024U * 1024U);
    server.Get("/", [](const httplib::Request&, httplib::Response& response) {
        response.set_content(std::string(medvision::web::kOfflineCameraPage), "text/html; charset=utf-8");
    });
    server.Get("/health", [pipeline, runtime](const httplib::Request&, httplib::Response& response) {
        reply(response, 200, {
            {"ok", true}, {"service", "medvision_cpp_offline_runtime"},
            {"runtime", "cpp20"}, {"offline", true}, {"python_required", false},
            {"frame_queue_capacity", 1}, {"state", medvision::to_string(runtime->state())},
            {"provider", pipeline->provider()},
            {"models", {
                {"device", {{"id", pipeline->config().detector_version}, {"sha256", kDetectorSha256}}},
                {"contact", {{"id", pipeline->config().contact_version}, {"sha256", kContactSha256}}},
                {"face", {{"id", pipeline->config().face_version}, {"sha256", kFaceSha256}, {"landmark_count", 478}}},
            }},
        });
    });
    server.Post("/v1/infer/image", [pipeline](const httplib::Request& request, httplib::Response& response) {
        try {
            if (request.body.empty()) throw std::invalid_argument("图片内容为空");
            const std::vector<std::uint8_t> bytes(request.body.begin(), request.body.end());
            auto result = pipeline->infer(bytes, 0, 0, true);
            result.state = result.device ? medvision::RuntimeState::Tracking : medvision::RuntimeState::Searching;
            result.bbox_source = result.device ? medvision::BBoxSource::YoloX : medvision::BBoxSource::None;
            reply(response, 200, {{"ok", true}, {"result", serialize(result)}});
        } catch (const std::invalid_argument& exception) {
            reply(response, 400, error("invalid_image", exception.what()));
        } catch (const std::exception& exception) {
            reply(response, 500, error("inference_failed", exception.what()));
        }
    });
    const auto reset_handler = [runtime](const httplib::Request&, httplib::Response& response) {
        runtime->reset();
        reply(response, 200, {{"ok", true}, {"state", "SEARCHING"}});
    };
    server.Post("/v1/stream/start", reset_handler);
    server.Post("/v1/stream/reset", reset_handler);
    server.Post("/v1/stream/frame", [runtime, &in_flight](const httplib::Request& request, httplib::Response& response) {
        if (in_flight.test_and_set()) {
            reply(response, 429, error("frame_in_flight", "上一帧仍在处理，本帧已丢弃"));
            return;
        }
        FlagGuard guard(in_flight);
        try {
            if (request.body.empty()) throw std::invalid_argument("JPEG帧为空");
            const std::vector<std::uint8_t> bytes(request.body.begin(), request.body.end());
            const cv::Mat encoded(1, static_cast<int>(bytes.size()), CV_8UC1, const_cast<std::uint8_t*>(bytes.data()));
            const cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
            if (bgr.empty()) throw std::invalid_argument("无法解码JPEG帧");
            const auto frame_id = header_integer(request, "X-Frame-Id", 0);
