namespace {

void require(bool condition, const std::string& message) {
    if (!condition) {
        std::cerr << "FAIL: " << message << "\n";
        std::exit(EXIT_FAILURE);
    }
}

bool close(float left, float right, float tolerance = 1e-3F) {
    return std::abs(left - right) <= tolerance;
}

}  // namespace

int main() {
    const auto transform = medvision::make_letterbox(4032, 3024, 640, 640);
    require(close(transform.scale, 640.0F / 4032.0F), "letterbox scale");
    const medvision::Point2f point{1000.0F, 500.0F};
    const auto restored = medvision::from_letterbox(medvision::to_letterbox(point, transform), transform);
    require(close(restored.x, point.x) && close(restored.y, point.y), "letterbox round trip");

    require(close(medvision::bbox_iou({0, 0, 10, 10}, {5, 5, 15, 15}), 25.0F / 175.0F), "bbox IoU");
    const std::vector<medvision::Point2f> square{{0, 0}, {10, 0}, {10, 10}, {0, 10}};
    require(medvision::point_in_polygon({5, 5}, square), "point inside polygon");
    require(!medvision::point_in_polygon({15, 5}, square), "point outside polygon");

    const std::vector<medvision::YoloXPrediction> predictions{
        {320, 320, 100, 200, 0.9F, 0.9F},
        {322, 322, 100, 200, 0.8F, 0.9F},
    };
    const auto detections = medvision::decode_yolox(predictions, 0.5F, 0.5F, transform);
    require(detections.size() == 1, "NMS suppresses overlapping detection");

    std::vector<float> heatmap(16, 0.0F);
    heatmap[6] = 0.9F;
    const auto peak = medvision::decode_heatmap_peak(heatmap, 4, 4, {0, 0, 400, 200}, 0.5F);
    require(peak.has_value() && close(peak->x, 250.0F) && close(peak->y, 75.0F), "heatmap decode");

    std::vector<float> weighted_heatmap(25, -10.0F);
    weighted_heatmap[12] = 2.0F;
    weighted_heatmap[13] = 2.0F;
    const auto weighted_peak = medvision::decode_heatmap_peak_neighborhood(
        weighted_heatmap, 5, 5, {0, 0, 400, 200}, 1);
    require(
        close(weighted_peak.x, 250.0F, 0.1F) && close(weighted_peak.y, 100.0F, 0.1F),
        "weighted heatmap neighborhood decode");

    medvision::FaceGeometry face{true, square, {{medvision::FaceRegion::Forehead, square}}};
    require(
        medvision::classify_face_region({5, 5}, face).region == medvision::FaceRegion::Forehead,
        "face region mapping");
    require(
        medvision::classify_face_region({15, 5}, face).region == medvision::FaceRegion::OutsideFace,
        "outside face mapping");

    std::vector<medvision::Point2f> landmarks(478, {50.0F, 50.0F});
    landmarks[10] = {50.0F, 20.0F};
    landmarks[152] = {50.0F, 80.0F};
    landmarks[234] = {20.0F, 50.0F};
    landmarks[454] = {80.0F, 50.0F};
    const auto gate = medvision::build_face_gate(landmarks, 100, 100);
    require(gate.has_value(), "face gate builds from MediaPipe landmarks");
    require(medvision::device_near_face({10, 10, 40, 40}, *gate), "near-face device accepted");
    require(!medvision::device_near_face({0, 90, 5, 99}, *gate), "far device rejected");
    require(medvision::contact_near_face({50, 50}, *gate), "face contact accepted");

    medvision::BoundedQueue<int> queue(2);
    queue.push_drop_oldest(1);
    queue.push_drop_oldest(2);
    queue.push_drop_oldest(3);
    require(queue.dropped() == 1, "bounded queue drop count");
    require(queue.wait_pop() == 2 && queue.wait_pop() == 3, "bounded queue keeps newest frames");
    queue.close();
    require(!queue.wait_pop().has_value(), "closed queue returns empty");

    std::cout << "MEDVISION_CORE_TESTS=PASS\n";
    return EXIT_SUCCESS;
}
