from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from PIL import Image, ImageOps


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--asset-root", type=Path, required=True)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--limit", type=int, default=100)
    args = parser.parse_args()
    asset_root = args.asset_root.resolve()
    sys.path.insert(0, str(asset_root))

    from src.integrated_pipeline import IntegratedPipeline

    source_rows = [
        json.loads(line)
        for line in args.source.read_text(encoding="utf-8").splitlines()
        if line
    ][: args.limit]
    pipeline = IntegratedPipeline(
        asset_root,
        detection_model=asset_root / "models/camera_active_v5/device/package/model.onnx",
        detection_model_id="device-yolox-s-640-camera-active-v5-real-only",
        contact_model=asset_root / "models/camera_active_v5/contact/package/model.onnx",
        contact_model_id="contact-mobilenet-v3-small-camera-active-v5",
        enable_face_region=False,
        enable_face_gate=True,
        providers=["CPUExecutionProvider"],
    )
    rows: list[dict[str, object]] = []
    try:
        for index, source in enumerate(source_rows):
            image_path = Path(str(source["image_path"]))
            with Image.open(image_path) as opened:
                image = ImageOps.exif_transpose(opened).convert("RGB")
            result = pipeline.infer(image, str(source["filename"]))
            rows.append({
                "index": index,
                "filename": source["filename"],
                "image_path": str(image_path),
                "image_width": image.width,
                "image_height": image.height,
                "detected_bbox": list(result.device.bbox) if result.device.bbox else None,
                "device_score": result.device.score if result.device.bbox else None,
                "predicted_point": list(result.contact.point) if result.contact.point else None,
                "contact_visibility": result.contact.visibility,
                "contact_confidence": result.contact.heatmap_confidence,
                "face_detected": result.face_detected,
                "needs_review": result.needs_review,
                "review_reasons": list(result.review_reasons),
            })
    finally:
        pipeline.close()

    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(
        "".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows),
        encoding="utf-8",
    )
    if len(rows) != args.limit:
        raise RuntimeError(f"expected {args.limit} rows, wrote {len(rows)}")
    print(f"CPP_OFFLINE_PYTHON_GOLD={args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
